// Normal-play registration batch. Existing guards never open here. A new
// interest/remap schedules at most one scan; absent aliases do not spin.
// The published ticket still rejects every JIT holding a pre-guard PTE.
bool refresh_persistent() noexcept {
    auto lock = hold();
    if (!collecting_ || !persistent_ || !stats_.observing || stats_.failed) return false;
    if (!refresh_pending_) return true;
    refresh_pending_ = false;
    try {
        for (auto &g : groups_) if (!g.armed || g.epoch != stats_.epoch) g.aliases.clear();
        for (uint32_t p = 1; p < page_count; ++p) {
            const auto entry = load(raw_, p);
            if (!entry) continue;
            const auto it = by_host_.find(host_page(entry, p));
            if (it != by_host_.end()) {
                auto &g = groups_[it->second];
                if (!g.armed || g.epoch != stats_.epoch) g.aliases.push_back(p);
            }
        }
        for (auto &g : groups_) {
            if ((g.armed && g.epoch == stats_.epoch) || g.aliases.empty()) continue;
            g.epoch = stats_.epoch; g.armed = true;
            ++count().armed_pages; count().armed_aliases += g.aliases.size();
            for (auto p : g.aliases) store(writes_.get(), p, nullptr);
        }
        for (auto &r : resources_) r.covered = std::all_of(r.groups.begin(), r.groups.end(), [&](uint32_t g) {
            return groups_[g].armed && groups_[g].epoch == stats_.epoch && !groups_[g].aliases.empty();
        });
        publication_ticket_ = domain_ ? domain_->publish() : 0;
        return true;
    } catch (...) { fail(); return false; }
}
